O=Path('outputs');G=json.loads((O/'generalization_data.json').read_text());D=json.loads((O/'direct_training_data.json').read_text())['main'];R=G['results'];C={'base':'#A9B1BD','language':'#147D79','budget':'#3976AF','six':'#8D66AD','sft':'#147D79'}
