def bars(ax,x,rs,colors,width=.58):
 for xx,r,col in zip(x,rs,colors):
  v=r.get('rate',r.get('mean_strict'))*100;lo,hi=np.array(r['ci95'])*100
  ax.bar(xx,v,width,color=col,zorder=3);ax.errorbar(xx,v,yerr=[[v-lo],[hi-v]],fmt='none',ecolor='#202A36',capsize=4,elinewidth=1.5,zorder=4)
  ax.text(xx,hi+2.8,f'{v:.1f}%' if v else '0%',ha='center',va='bottom',fontsize=16,fontweight='bold')
bars(axs[0],range(3),[D[m] for m in ['base','lang1-s40','len2']],[C['base'],C['language'],C['budget']]);axs[0].set_xticks(range(3),['Base','Language\nRL','Budget\nRL']);axs[0].set_xlabel('GPT-OSS · CoT-control benchmark',labelpad=11,fontsize=15);axs[0].set_ylabel('Strict Compliance',fontsize=16)
